function putScreen(title,body,ref,mode,background){activeScreenBackground=background||null;document.getElementById('ws-slide-title').value=title||'';document.getElementById('ws-slide-body').value=body||'';document.getElementById('ws-slide-reference').value=ref||'';if(mode)document.getElementById('ws-mode').value=mode;saveSlide();preview();}
function bibleSearch(){var q=val('ws-bible-query').trim().toLowerCase(),host=document.getElementById('ws-bible-results');if(!host)return;var found=kjvBooks.map(function(b,i){return {code:b[0],name:b[1],index:i};}).filter(function(b){return !q||b.name.toLowerCase().startsWith(q)||b.code.toLowerCase().startsWith(q)||b.name.toLowerCase().includes(q);}).slice(0,12);host.innerHTML=found.map(function(b){return '<button type="button" class="ws-bible-result" role="option" data-book="'+b.index+'"><strong>'+esc(b.name)+'</strong><span>'+esc(b.code)+'</span></button>';}).join('')||'<p class="worship-hint">No Bible book matches that search.</p>';}
async function loadKJVBook(index,chapter,verse){try{if(index<0||index>=kjvBooks.length)return;var meta=kjvBooks[index];msg('Loading '+meta[1]+' · King James Version…','warning');if(!kjvCache[meta[0]]){var url='/api/public/bible/kjv/'+meta[0];var response=await fetch(url);if(!response.ok)throw new Error('Could not load '+meta[1]+'. Check your internet connection and try again.');var data=await response.json();if(!Array.isArray(data.chapters)||!data.chapters.length)throw new Error('The KJV book data is incomplete.');kjvCache[meta[0]]=data;}kjvLoaded=kjvCache[meta[0]];kjvCurrent={book:index,chapter:Math.max(1,Math.min(chapter||1,kjvLoaded.chapters.length)),verse:1};var bs=document.getElementById('ws-bible-book'),cs=document.getElementById('ws-bible-chapter');if(bs)bs.value=String(index);if(cs){cs.innerHTML=kjvLoaded.chapters.map(function(c){return '<option value="'+c.chapter+'">Chapter '+c.chapter+'</option>';}).join('');cs.disabled=false;cs.value=String(kjvCurrent.chapter);}renderKJVChapter(verse||1);msg(meta[1]+' loaded · King James Version','success');}catch(e){msg(e.message,'error');}}
function renderKJVChapter(verse){if(!kjvLoaded)return;var chapter=kjvLoaded.chapters.find(function(c){return c.chapter===kjvCurrent.chapter;});if(!chapter)return;kjvCurrent.verse=Math.max(1,Math.min(verse||1,chapter.verses.length));var vs=document.getElementById('ws-bible-verse');vs.innerHTML=chapter.verses.map(function(v){return '<option value="'+v.number+'">Verse '+v.number+'</option>';}).join('');vs.disabled=false;vs.value=String(kjvCurrent.verse);var item=chapter.verses.find(function(v){return v.number===kjvCurrent.verse;});var ref=kjvBooks[kjvCurrent.book][1]+' '+kjvCurrent.chapter+':'+kjvCurrent.verse;document.getElementById('ws-scripture-ref').value=ref;document.getElementById('ws-scripture-text').value=item.text;document.getElementById('ws-bible-reading').innerHTML='<strong>'+esc(ref)+' · KJV</strong><p>'+esc(item.text)+'</p>';document.getElementById('ws-bible-prev').disabled=kjvCurrent.book===0&&kjvCurrent.chapter===1&&kjvCurrent.verse===1;document.getElementById('ws-bible-next').disabled=kjvCurrent.book===65&&kjvCurrent.chapter===kjvLoaded.chapters.length&&kjvCurrent.verse===chapter.verses.length;document.getElementById('ws-bible-publish').disabled=false;if(session&&session.status==='live'){var mode=val('ws-bible-style')||'overlay';document.getElementById('ws-mode').value=mode;putScreen('',item.text,ref,mode,mode==='slide'?(val('ws-bible-theme')||'#071329'):null);publish();}}
async function stepKJV(delta){if(!kjvLoaded)return;var ch=kjvLoaded.chapters.find(function(c){return c.chapter===kjvCurrent.chapter;}),next=kjvCurrent.verse+delta;if(next>ch.verses.length){if(kjvCurrent.chapter<kjvLoaded.chapters.length){await loadKJVBook(kjvCurrent.book,kjvCurrent.chapter+1,1);return;}if(kjvCurrent.book<65){await loadKJVBook(kjvCurrent.book+1,1,1);return;}return;}if(next<1){if(kjvCurrent.chapter>1){await loadKJVBook(kjvCurrent.book,kjvCurrent.chapter-1,9999);return;}if(kjvCurrent.book>0){await loadKJVBook(kjvCurrent.book-1,9999,9999);return;}return;}renderKJVChapter(next);}
function publishKJV(){if(!kjvLoaded)return;var ref=val('ws-scripture-ref'),txt=val('ws-scripture-text'),mode=val('ws-bible-style')||'overlay',theme=val('ws-bible-theme')||'#071329';document.getElementById('ws-mode').value=mode;putScreen('',txt,ref,mode,mode==='slide'?theme:null);publish();msg('Publishing '+ref+' · KJV','success');}
function prepareHymnStanzas(){hymnStanzas=val('ws-hymn-lyrics').split(/\n\s*\n/).map(function(x){return x.trim();}).filter(Boolean);hymnStanzaIndex=0;updateHymnStanzaStatus();}
function updateHymnStanzaStatus(){var e=document.getElementById('ws-hymn-stanza-status');if(e)e.textContent=hymnStanzas.length?'Stanza '+(hymnStanzaIndex+1)+' of '+hymnStanzas.length:'Separate stanzas with a blank line';var p=document.getElementById('ws-hymn-prev'),n=document.getElementById('ws-hymn-next');if(p)p.disabled=!hymnStanzas.length||hymnStanzaIndex===0;if(n)n.disabled=!hymnStanzas.length||hymnStanzaIndex>=hymnStanzas.length-1;}
function moveHymnStanza(delta){if(!hymnStanzas.length)prepareHymnStanzas();var next=hymnStanzaIndex+delta;if(next<0||next>=hymnStanzas.length)return;hymnStanzaIndex=next;var stanza=hymnStanzas[hymnStanzaIndex];document.getElementById('ws-hymn-lyrics').value=stanza;updateHymnStanzaStatus();putScreen(val('ws-hymn-title'),stanza,val('ws-hymn-meta')+' · Stanza '+(hymnStanzaIndex+1)+' of '+hymnStanzas.length,val('ws-hymn-style')||'overlay');if(session&&session.status==='live')publish();}
function publishHymn(){prepareHymnStanzas();if(!hymnStanzas.length){msg('Select a hymn or enter authorised lyrics first.','error');return;}hymnStanzaIndex=0;var stanza=hymnStanzas[0];document.getElementById('ws-hymn-lyrics').value=stanza;updateHymnStanzaStatus();var mode=val('ws-hymn-style')||'overlay';document.getElementById('ws-mode').value=mode;putScreen(val('ws-hymn-title'),stanza,val('ws-hymn-meta')+' · Stanza 1 of '+hymnStanzas.length,mode);publish();msg('Publishing '+val('ws-hymn-title')+' · Stanza 1','success');}
function payload(){return {title:val('ws-title'),description:val('ws-description'),overlayText:val('ws-welcome'),scriptureReference:val('ws-scripture-ref'),scriptureText:val('ws-scripture-text'),logoUrl:val('ws-logo-url'),logoPosition:val('ws-logo-position'),recordingEnabled:yes('ws-recording'),isPublic:yes('ws-public'),presentationConfig:config()};}
function share(path){document.getElementById('ws-share').hidden=false;document.getElementById('ws-share-url').value=location.origin+path;var phone=document.getElementById('ws-phone-url');if(phone&&session)phone.value=location.origin+'/camera.html?slug='+encodeURIComponent(session.slug);}
function history(){req('/admin/broadcast/sessions').then(function(d){document.getElementById('ws-history').innerHTML=(d.sessions||[]).slice(0,12).map(function(s){return '<div class="worship-history-row"><span><strong>'+esc(s.title)+'</strong><small>'+esc(s.status)+' · '+esc(new Date(s.created_at).toLocaleString())+'</small></span><span>'+esc(s.recording_status)+'</span></div>';}).join('')||'<p>No broadcasts yet.</p>';}).catch(function(e){document.getElementById('ws-history').textContent=e.message;});}
async function upload(id,target){var f=document.getElementById(id).files[0];if(!f)return '';if(f.size>15*1024*1024)throw new Error('File must be 15 MB or smaller.');var fd=new FormData();fd.append('file',f);var d=await req('/admin/uploads?bucket=church-public','POST',fd);document.getElementById(target).value=d.url;preview();return d.url;}
async function saveDraft(){try{var p=payload();if(session){await req('/admin/broadcast/sessions/'+session.id+'/overlay','PATCH',{overlayText:p.overlayText,scriptureReference:p.scriptureReference,scriptureText:p.scriptureText,presentationConfig:p.presentationConfig});msg('Broadcast setup updated','success');return;}if(String(p.title).trim().length<3)throw new Error('Enter a broadcast title (at least 3 characters).');var d=await req('/admin/broadcast/sessions','POST',p);session=d.session;share(d.shareUrl);history();msg('Broadcast setup saved','success');}catch(e){msg(e.message,'error');}}
async function startPreview(){
  var previous=mainStream,oldVideo=videoTrack,oldAudio=audioTrack,nextVideoStream=null,nextAudioStream=null;
  try{
    if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia)throw new Error('Camera access requires HTTPS and a browser that supports camera capture.');
    var id=val('ws-camera'),dims={'480p':[854,480],'720p':[1280,720],'1080p':[1920,1080]}[val('ws-quality')||'720p']||[1280,720];
    if(room){
      if(oldVideo)await room.localParticipant.unpublishTrack(oldVideo);
      if(oldAudio)await room.localParticipant.unpublishTrack(oldAudio);
      videoTrack=null;audioTrack=null;
    }
    if(previous){previous.getTracks().forEach(function(t){t.stop();});mainStream=null;}
    var videoBase={width:{ideal:dims[0]},height:{ideal:dims[1]},frameRate:{ideal:30,max:30}};
    var attempts=[];
    if(id)attempts.push({video:Object.assign({},videoBase,{deviceId:{exact:id}}),audio:false});
    attempts.push({video:Object.assign({},videoBase,{facingMode:{ideal:'environment'}}),audio:false});
    attempts.push({video:true,audio:false});
    var lastError=null;
    for(var ai=0;ai<attempts.length;ai++){
      try{nextVideoStream=await navigator.mediaDevices.getUserMedia(attempts[ai]);break;}
      catch(cameraError){lastError=cameraError;}
    }
    if(!nextVideoStream)throw new Error('Camera could not start ('+(lastError&&lastError.name||'camera error')+'): '+(lastError&&lastError.message||'Check that the camera is not being used by another app, allow camera permission, and try Refresh devices.'));
    var tracks=nextVideoStream.getVideoTracks();
    if(!tracks.length)throw new Error('The selected device did not provide a video track.');
    var micId=val('ws-mic');
    try{nextAudioStream=await navigator.mediaDevices.getUserMedia({video:false,audio:micId?{deviceId:{exact:micId}}:true});}
    catch(micError){nextAudioStream=null;msg('Camera ready. Microphone unavailable ('+(micError.name||'audio error')+'); you can continue with camera audio disabled.','warning');}
    var allTracks=tracks.slice();
    if(nextAudioStream)allTracks=allTracks.concat(nextAudioStream.getAudioTracks());
    mainStream=new MediaStream(allTracks);
    window.icfPreviewStream=mainStream;
    var v=document.getElementById('ws-preview');v.srcObject=mainStream;v.muted=true;v.autoplay=true;v.playsInline=true;await v.play();
    if(room){
      var liveVideo=tracks[0];
      if(liveVideo.readyState!=='live')throw new Error('The camera stopped before it could be published. Reopen the preview and try again.');
      videoTrack=new LivekitClient.LocalVideoTrack(liveVideo);
      await room.localParticipant.publishTrack(videoTrack,{name:'icf-camera-main'});
      var micTrack=mainStream.getAudioTracks()[0];
      if(micTrack){audioTrack=new LivekitClient.LocalAudioTrack(micTrack);await room.localParticipant.publishTrack(audioTrack,{name:'icf-microphone'});}
    }
    if(nextAudioStream)nextAudioStream=null;
    await devicesList();preview();
    msg(room?'Camera source switched · live output updated':'Camera preview ready · '+(mainStream.getAudioTracks().length?'camera and microphone connected':'camera connected without microphone'),'success');
  }catch(e){
    if(nextVideoStream)nextVideoStream.getTracks().forEach(function(t){t.stop();});
    if(nextAudioStream)nextAudioStream.getTracks().forEach(function(t){t.stop();});
    var label=document.querySelector('#ws-stage .worship-preview-label');
    if(label&&!(room&&room.state==='connected'))label.textContent='PREVIEW · NOT PUBLIC';
    var name=e&&e.name||'';
    var hint=name==='NotAllowedError'?'Allow camera permission in your browser settings.':name==='NotFoundError'?'No camera was found on this device.':name==='NotReadableError'?'The camera is busy. Close other camera apps or browser tabs, then retry.':name==='OverconstrainedError'?'That camera does not support the requested setting. Refresh devices and retry.':'';
    msg((e&&e.message||'Could not start video source.')+(hint?' '+hint:''),'error');
    throw e;
  }
}
async function addCamera(){try{var id=val('ws-camera-2');if(!id)throw new Error('Select a second camera first.');if(id==='remote'){if(!session||!room)throw new Error('Start the broadcast first, then connect the phone using the pairing link.');remoteCameraReady=true;preview();msg('Phone camera pairing enabled. Open the phone camera link on your phone.','success');return;}if(secondStream)secondStream.getTracks().forEach(function(t){t.stop();});secondStream=await navigator.mediaDevices.getUserMedia({video:{deviceId:{exact:id}},audio:false});var v=document.getElementById('ws-preview-2');v.srcObject=secondStream;v.hidden=false;await v.play();if(room){secondTrack=new LivekitClient.LocalVideoTrack(secondStream.getVideoTracks()[0]);await room.localParticipant.publishTrack(secondTrack,{name:'icf-camera-secondary'});}preview();msg('Second camera connected','success');}catch(e){msg('Second camera unavailable: '+e.message,'warning');}}
async function switchCamera(){if(!devices.video.length)return msg('No camera detected','warning');var e=document.getElementById('ws-camera'),i=devices.video.findIndex(function(d){return d.deviceId===e.value;});e.value=devices.video[(i+1)%devices.video.length].deviceId;await startPreview();}
var BUILTIN_HYMNS = [
{ id:"pd-rock-of-ages", title:"Rock of Ages", hymn_number:"Augustus M. Toplady · 1776 · Public domain", lyrics:"Rock of Ages, cleft for me,\nLet me hide myself in thee;\nLet the water and the blood,\nFrom thy wounded side which flowed,\nBe of sin the double cure,\nSave me from its guilt and power.\n\nNot the labours of my hands\nCan fulfil thy law’s demands;\nCould my zeal no respite know,\nCould my tears for ever flow,\nAll for sin could not atone;\nThou must save, and thou alone.\n\nNothing in my hand I bring,\nSimply to thy cross I cling;\nNaked, come to thee for dress;\nHelpless, look to thee for grace;\nFoul, I to the fountain fly;\nWash me, Saviour, or I die.\n\nWhile I draw this fleeting breath,\nWhen mine eyes shall close in death,\nWhen I rise to worlds unknown,\nAnd behold thee on thy throne,\nRock of Ages, cleft for me,\nLet me hide myself in thee." },
{ id:"pd-my-hope", title:"My Hope Is Built on Nothing Less", hymn_number:"Edward Mote · 1834 · Public domain", lyrics:"My hope is built on nothing less\nThan Jesus’ blood and righteousness;\nI dare not trust the sweetest frame,\nBut wholly lean on Jesus’ name.\n\nChorus:\nOn Christ, the solid Rock, I stand;\nAll other ground is sinking sand,\nAll other ground is sinking sand.\n\nWhen darkness veils His lovely face,\nI rest on His unchanging grace;\nIn every high and stormy gale,\nMy anchor holds within the veil.\n\nChorus:\nOn Christ, the solid Rock, I stand;\nAll other ground is sinking sand,\nAll other ground is sinking sand.\n\nHis oath, His covenant, His blood,\nSupport me in the whelming flood;\nWhen all around my soul gives way,\nHe then is all my hope and stay.\n\nChorus:\nOn Christ, the solid Rock, I stand;\nAll other ground is sinking sand,\nAll other ground is sinking sand.\n\nWhen He shall come with trumpet sound,\nOh, may I then in Him be found;\nDressed in His righteousness alone,\nFaultless to stand before the throne.\n\nChorus:\nOn Christ, the solid Rock, I stand;\nAll other ground is sinking sand,\nAll other ground is sinking sand." },
{ id:"pd-amazing-grace", title:"Amazing Grace", hymn_number:"John Newton · 1779 · Public domain", lyrics:"Amazing grace! how sweet the sound\nThat saved a wretch like me!\nI once was lost, but now am found;\nWas blind, but now I see.\n\n’Twas grace that taught my heart to fear,\nAnd grace my fears relieved;\nHow precious did that grace appear\nThe hour I first believed!\n\nThrough many dangers, toils and snares,\nI have already come;\n’Tis grace hath brought me safe thus far,\nAnd grace will lead me home.\n\nThe Lord has promised good to me,\nHis word my hope secures;\nHe will my shield and portion be\nAs long as life endures." },
{ id:"pd-blessed-assurance", title:"Blessed Assurance", hymn_number:"Fanny J. Crosby · 1873 · Public domain", lyrics:"Blessed assurance, Jesus is mine!\nO what a foretaste of glory divine!\nHeir of salvation, purchase of God,\nBorn of His Spirit, washed in His blood.\n\nRefrain:\nThis is my story, this is my song,\nPraising my Saviour all the day long;\nThis is my story, this is my song,\nPraising my Saviour all the day long.\n\nPerfect submission, perfect delight,\nVisions of rapture now burst on my sight;\nAngels descending bring from above\nEchoes of mercy, whispers of love.\n\nRefrain:\nThis is my story, this is my song,\nPraising my Saviour all the day long;\nThis is my story, this is my song,\nPraising my Saviour all the day long.\n\nPerfect submission, all is at rest;\nI in my Saviour am happy and blest,\nWatching and waiting, looking above,\nFilled with His goodness, lost in His love.\n\nRefrain:\nThis is my story, this is my song,\nPraising my Saviour all the day long;\nThis is my story, this is my song,\nPraising my Saviour all the day long." },
{ id:"pd-holy-holy-holy", title:"Holy, Holy, Holy! Lord God Almighty", hymn_number:"Reginald Heber · 1826 · Public domain", lyrics:"Holy, holy, holy! Lord God Almighty!\nEarly in the morning our song shall rise to Thee;\nHoly, holy, holy! merciful and mighty!\nGod in three Persons, blessed Trinity!\n\nHoly, holy, holy! all the saints adore Thee,\nCasting down their golden crowns around the glassy sea;\nCherubim and seraphim falling down before Thee,\nWho wert, and art, and evermore shalt be.\n\nHoly, holy, holy! though the darkness hide Thee,\nThough the eye of sinful man Thy glory may not see;\nOnly Thou art holy; there is none beside Thee,\nPerfect in power, in love, and purity.\n\nHoly, holy, holy! Lord God Almighty!\nAll Thy works shall praise Thy name, in earth, and sky, and sea;\nHoly, holy, holy! merciful and mighty!\nGod in three Persons, blessed Trinity!" },
{ id:"pd-what-a-friend", title:"What a Friend We Have in Jesus", hymn_number:"Joseph M. Scriven · 1855 · Public domain", lyrics:"What a Friend we have in Jesus,\nAll our sins and griefs to bear!\nWhat a privilege to carry\nEverything to God in prayer!\nO what peace we often forfeit,\nO what needless pain we bear,\nAll because we do not carry\nEverything to God in prayer!\n\nHave we trials and temptations?\nIs there trouble anywhere?\nWe should never be discouraged;\nTake it to the Lord in prayer.\nCan we find a Friend so faithful\nWho will all our sorrows share?\nJesus knows our every weakness;\nTake it to the Lord in prayer.\n\nAre we weak and heavy laden,\nCumbered with a load of care?\nPrecious Saviour, still our refuge—\nTake it to the Lord in prayer.\nDo thy friends despise, forsake thee?\nTake it to the Lord in prayer;\nIn His arms He’ll take and shield thee;\nThou wilt find a solace there." }
];
function hymnSearchText(h){return (h.title+" "+(h.hymn_number||"")+" "+h.lyrics).toLocaleLowerCase().replace(/[’‘]/g,"'");}
function renderHymnResults(){
 var q=val("ws-hymn-query").trim().toLocaleLowerCase().replace(/[’‘]/g,"'"),all=BUILTIN_HYMNS.concat(hymnLibrary),seen={},matches=[];
 all.forEach(function(h){var key=(h.title||"").toLowerCase()+"|"+(h.lyrics||"");if(seen[key])return;seen[key]=true;if(!q||hymnSearchText(h).indexOf(q)>=0)matches.push(h);});
 var host=document.getElementById("ws-hymn-results");if(!host)return;
 host.innerHTML=matches.slice(0,60).map(function(h){return '<button type="button" class="ws-slide-chip" data-hymn="'+esc(h.id)+'"><strong>'+esc(h.title)+'</strong><span>'+esc(h.hymn_number||"")+'</span></button>';}).join("")||'<p class="worship-hint">No matching hymn found. Try a title, chorus phrase or another lyric.</p>';
}
function selectHymn(h){
 if(!h)return;
 document.getElementById("ws-hymn-title").value=h.title||"";
 document.getElementById("ws-hymn-meta").value=h.hymn_number||"";
 document.getElementById("ws-hymn-lyrics").value=h.lyrics||"";
 prepareHymnStanzas();
 var note=document.getElementById("ws-hymn-source-note");
 if(note)note.textContent=(String(h.id).indexOf("pd-")===0?"Historic public-domain hymn text selected. ":"Saved ICF hymn selected. ")+"Select Publish hymn to put it on screen.";
 msg("Hymn loaded · "+h.title,"success");
}
function loadHymnary(){
 renderHymnResults();
 req("/admin/broadcast/hymns").then(function(d){hymnLibrary=d.hymns||[];var e=document.getElementById("ws-hymn-library");if(e)e.innerHTML=hymnLibrary.map(function(h){return '<button type="button" class="ws-slide-chip" data-hymn="'+esc(h.id)+'"><strong>'+esc(h.title)+'</strong><span>Saved ICF hymn</span></button>';}).join("")||'<p class="worship-hint">Your church-approved custom hymns will appear here.</p>';renderHymnResults();}).catch(function(e){var h=document.getElementById("ws-hymn-library");if(h)h.textContent="Saved ICF hymns could not load: "+e.message;});
}async function saveHymn(){try{var title=val('ws-hymn-title').trim(),lyrics=val('ws-hymn-lyrics').trim();if(title.length<2||!lyrics)throw new Error('Enter the hymn title and authorised lyrics first.');await req('/admin/broadcast/hymns','POST',{title:title,hymnNumber:val('ws-hymn-meta'),lyrics:lyrics});msg('Hymn saved to the ICF hymnary','success');loadHymnary();}catch(e){msg(e.message,'error');}}
async function goLive(){try{if(!window.LivekitClient)throw new Error('LiveKit browser library did not load. Refresh the page.');if(!mainStream)await startPreview();if(!mainStream)throw new Error('Start the camera preview first.');if(!session){var p=payload();if(String(p.title).trim().length<3)throw new Error('Enter a broadcast title first.');var d=await req('/admin/broadcast/sessions','POST',p);session=d.session;share(d.shareUrl);}else{var c=config();await req('/admin/broadcast/sessions/'+session.id+'/overlay','PATCH',{overlayText:val('ws-welcome'),scriptureReference:val('ws-scripture-ref'),scriptureText:val('ws-scripture-text'),presentationConfig:c});}msg('Connecting to LiveKit…','warning');var t=await req('/admin/broadcast/sessions/'+session.id+'/token','POST',{});room=new LivekitClient.Room({adaptiveStream:true,dynacast:true});room.on(LivekitClient.RoomEvent.TrackSubscribed,function(track,publication){if(track.kind==='video'&&publication&&publication.trackName==='icf-camera-secondary'){remoteCameraReady=true;var el=track.attach(),target=document.getElementById('ws-preview-2');el.id='ws-preview-2';el.autoplay=true;el.playsInline=true;if(target&&target!==el)target.replaceWith(el);preview();msg('Phone camera connected','success');}});room.on(LivekitClient.RoomEvent.TrackUnsubscribed,function(track,publication){if(publication&&publication.trackName==='icf-camera-secondary'){remoteCameraReady=false;var target=document.getElementById('ws-preview-2');if(target){target.srcObject=null;target.hidden=true;}preview();}});await room.connect(t.serverUrl,t.token);videoTrack=new LivekitClient.LocalVideoTrack(mainStream.getVideoTracks()[0]);await room.localParticipant.publishTrack(videoTrack,{name:'icf-camera-main'});if(mainStream.getAudioTracks()[0]){audioTrack=new LivekitClient.LocalAudioTrack(mainStream.getAudioTracks()[0]);await room.localParticipant.publishTrack(audioTrack,{name:'icf-microphone'});}if(secondStream){secondTrack=new LivekitClient.LocalVideoTrack(secondStream.getVideoTracks()[0]);await room.localParticipant.publishTrack(secondTrack,{name:'icf-camera-secondary'});}var live=await req('/admin/broadcast/sessions/'+session.id+'/start','POST',{});session=live.session;if(yes('ws-recording')){var stream=new MediaStream(mainStream.getTracks()),mime=MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus')?'video/webm;codecs=vp9,opus':'video/webm';recorder=new MediaRecorder(stream,{mimeType:mime});chunks=[];recorder.ondataavailable=function(e){if(e.data.size)chunks.push(e.data);};recorder.start(1000);req('/admin/broadcast/sessions/'+session.id+'/recording','PATCH',{status:'local_recording'}).catch(function(){});}document.getElementById('ws-go-live').disabled=true;document.getElementById('ws-end-live').disabled=false;share('/live.html?slug='+encodeURIComponent(session.slug));var liveLabel=document.querySelector('#ws-stage .worship-preview-label');if(liveLabel)liveLabel.textContent=yes('ws-public')?'🔴 ON AIR · PUBLIC':'🔴 ON AIR · PRIVATE';document.getElementById('ws-stage').dataset.onair='true';msg(yes('ws-recording')?'🔴 LIVE · local recording enabled':(yes('ws-public')?'🔴 LIVE · public viewers can join':'🔴 LIVE · private broadcast'),'live');history();}catch(e){if(room){await room.disconnect().catch(function(){});room=null;}var label=document.querySelector('#ws-stage .worship-preview-label');if(label)label.textContent='PREVIEW · NOT PUBLIC';var detail=String(e&&e.message||e);if(/signal connection|Failed to fetch|WebSocket|could not establish/i.test(detail)){console.error('ICF LiveKit room.connect failed:',e);detail='LiveKit could not connect to the signal server: '+detail+'. Confirm the Render LIVEKIT_URL is the exact wss:// Project URL from this same LiveKit project, then check browser network/WebSocket access. Camera preview is local only; this service has NOT gone live.';}msg(detail,'error');}}
async function publish(){try{preview();var p=payload();if(!session||session.status!=='live'){msg('Preview updated. Save setup or go live to publish it.','success');return;}await req('/admin/broadcast/sessions/'+session.id+'/overlay','PATCH',{overlayText:p.overlayText,scriptureReference:p.scriptureReference,scriptureText:p.scriptureText,presentationConfig:p.presentationConfig});msg('LIVE · Screen updated for viewers','success');}catch(e){msg(e.message,'error');}}
async function endLive(){
  if(!window.confirm('End the ICF broadcast for all viewers? This will disconnect the live service.'))return;
  var ending=session,serverConfirmed=false,recordingWarning='';
  try{
    if(ending){
      msg('Closing the public broadcast…','warning');
      var result=await req('/admin/broadcast/sessions/'+ending.id+'/end','POST',{});
      serverConfirmed=!!result.ended;
      if(!serverConfirmed)throw new Error('The server did not confirm that the broadcast ended. Please retry.');
    }
    if(recorder&&recorder.state!=='inactive'){
      try{
        await new Promise(function(resolve){var finished=false;function done(){if(finished)return;finished=true;resolve();}recorder.addEventListener('stop',done,{once:true});recorder.stop();setTimeout(done,5000);});
        if(chunks.length){var blob=new Blob(chunks,{type:recorder.mimeType||'video/webm'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ICF-'+(ending&&ending.slug||'service')+'-'+Date.now()+'.webm';a.click();setTimeout(function(){URL.revokeObjectURL(url);},60000);}
        if(ending)await req('/admin/broadcast/sessions/'+ending.id+'/recording','PATCH',{status:'downloaded'}).catch(function(){});
      }catch(recordError){recordingWarning=' Recording could not be downloaded automatically.';}
      recorder=null;chunks=[];
    }
    if(room){try{await room.disconnect();}catch(_e){}room=null;}
    [mainStream,secondStream].forEach(function(stream){if(stream)stream.getTracks().forEach(function(track){track.stop();});});
    mainStream=null;secondStream=null;remoteCameraReady=false;window.icfPreviewStream=null;
    var p1=document.getElementById('ws-preview'),p2=document.getElementById('ws-preview-2');if(p1)p1.srcObject=null;if(p2)p2.srcObject=null;
    var go=document.getElementById('ws-go-live'),end=document.getElementById('ws-end-live');if(go)go.disabled=false;if(end)end.disabled=true;
    var label=document.querySelector('#ws-stage .worship-preview-label');if(label)label.textContent='PREVIEW · NOT PUBLIC';
    var stage=document.getElementById('ws-stage');if(stage)stage.dataset.onair='false';
    var shareBox=document.getElementById('ws-share');if(shareBox)shareBox.hidden=true;
    session=null;preview();msg('Broadcast ended · public live status is now OFFLINE.'+recordingWarning,'success');history();
    if(serverConfirmed)window.dispatchEvent(new CustomEvent('icf:broadcast-ended',{detail:{sessionId:ending&&ending.id}}));
  }catch(e){
    if(serverConfirmed){
      if(room){try{await room.disconnect();}catch(_e){}room=null;}
      [mainStream,secondStream].forEach(function(stream){if(stream)stream.getTracks().forEach(function(track){track.stop();});});mainStream=secondStream=null;session=null;
      var go=document.getElementById('ws-go-live'),end=document.getElementById('ws-end-live');if(go)go.disabled=false;if(end)end.disabled=true;
      var stage=document.getElementById('ws-stage');if(stage)stage.dataset.onair='false';
      var label=document.querySelector('#ws-stage .worship-preview-label');if(label)label.textContent='PREVIEW · NOT PUBLIC';
      msg('Broadcast ended on the server. Local studio cleanup had a problem: '+e.message,'warning');history();
    }else msg(e.message,'error');
  }
}
