window.watchIcfLive=function(){fetch('/api/public/live').then(function(r){if(!r.ok)throw new Error('The ICF live service is currently offline.');return r.json();}).then(function(d){if(!d.live||!d.session||!d.session.slug)throw new Error('ICF is not broadcasting at the moment. Please check again during the service.');window.location.href='/live.html?slug='+encodeURIComponent(d.session.slug);}).catch(function(e){window.alert(e.message||'Unable to open the live broadcast.');});};
window.renderLivestreamWidget=function(){var h=document.getElementById('livestream-widget');if(!h)return;fetch('/api/public/live').then(function(r){if(!r.ok)throw new Error('offline');return r.json();}).then(function(d){var links=document.querySelectorAll('[data-icf-watch-live]');links.forEach(function(a){a.textContent=d.live?'🔴 WATCH LIVE NOW':'▷ Watch Live';a.classList.toggle('is-live',!!d.live);});if(!d.live){h.style.display='none';h.innerHTML='';return;}h.style.display='block';h.innerHTML='<a class="icf-live-home-card" href="/live.html?slug='+encodeURIComponent(d.session.slug)+'"><span class="icf-live-pulse"></span><span><strong>ICF IS LIVE NOW</strong><small>'+esc(d.session.title)+'</small></span><b>WATCH LIVE →</b></a>';}).catch(function(){var links=document.querySelectorAll('[data-icf-watch-live]');links.forEach(function(a){a.textContent='▷ Watch Live';a.classList.remove('is-live');});h.style.display='none';});};
